CREATE UNIQUE INDEX IF NOT EXISTS pending_publications_user_product_pending_uidx ON public.pending_publications(user_id, product_id) WHERE status = 'pending';
ALTER TABLE public.pending_publications ADD COLUMN IF NOT EXISTS support_notified_at timestamptz;
CREATE OR REPLACE FUNCTION public.publication_image_gate(p_background boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE state jsonb; until_at timestamptz; BEGIN INSERT INTO public.job_locks(job) VALUES ('publication-image-circuit') ON CONFLICT DO NOTHING; SELECT last_result,locked_until INTO state,until_at FROM public.job_locks WHERE job='publication-image-circuit' FOR UPDATE; IF state->>'kind'='terminal' OR until_at>now() THEN RETURN false; END IF; IF state->>'kind' IN ('credit','rate','temporary') THEN UPDATE public.job_locks SET locked_until=now()+interval '5 minutes' WHERE job='publication-image-circuit'; END IF; RETURN true; END $$;
CREATE OR REPLACE FUNCTION public.publication_image_pause(p_kind text,p_message text,p_delay_seconds integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF p_kind NOT IN ('credit','rate','terminal','temporary') THEN RAISE EXCEPTION 'Invalid pause'; END IF; INSERT INTO public.job_locks(job,locked_until,last_result) VALUES ('publication-image-circuit',now()+make_interval(secs=>greatest(300,p_delay_seconds)),jsonb_build_object('kind',p_kind,'message',p_message,'paused_at',now())) ON CONFLICT(job) DO UPDATE SET locked_until=excluded.locked_until,last_result=excluded.last_result WHERE public.job_locks.last_result->>'kind' IS DISTINCT FROM 'terminal'; END $$;
CREATE OR REPLACE FUNCTION public.publication_image_resume_after_success() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.job_locks SET locked_until=now(),last_result='{}'::jsonb WHERE job='publication-image-circuit' AND last_result->>'kind' IS DISTINCT FROM 'terminal'; $$;
CREATE OR REPLACE FUNCTION public.claim_publication_worker(p_owner uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE claimed boolean; BEGIN INSERT INTO public.job_locks(job,locked_until,last_result) VALUES ('auto-publish-pending-worker',now()+interval '10 minutes',jsonb_build_object('owner',p_owner)) ON CONFLICT(job) DO UPDATE SET locked_until=excluded.locked_until,last_result=excluded.last_result WHERE public.job_locks.locked_until<=now(); claimed:=FOUND; RETURN claimed; END $$;
CREATE OR REPLACE FUNCTION public.release_publication_worker(p_owner uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.job_locks SET locked_until=now() WHERE job='auto-publish-pending-worker' AND last_result->>'owner'=p_owner::text; $$;
CREATE OR REPLACE FUNCTION public.enqueue_image_publication(p_user_id uuid,p_product_id text,p_title text,p_payload jsonb,p_active_limit integer,p_monthly_limit integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result_id uuid; pending_count integer; active_count integer; monthly_count integer; BEGIN IF length(p_product_id)=0 OR length(p_title)=0 OR jsonb_typeof(p_payload->'product') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Dados do produto inválidos'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text,0)); SELECT id INTO result_id FROM public.pending_publications WHERE user_id=p_user_id AND product_id=p_product_id AND status='pending'; IF result_id IS NOT NULL THEN RETURN result_id; END IF; SELECT count(*) INTO pending_count FROM public.pending_publications WHERE user_id=p_user_id AND status='pending'; SELECT count(*) FILTER(WHERE status IN ('active','published')),count(*) FILTER(WHERE created_at>=date_trunc('month',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC') INTO active_count,monthly_count FROM public.user_publications WHERE user_id=p_user_id; IF p_active_limit IS NOT NULL AND active_count+pending_count>=p_active_limit THEN RAISE EXCEPTION 'Limite de anúncios do plano atingido'; END IF; IF p_monthly_limit IS NOT NULL AND monthly_count+pending_count>=p_monthly_limit THEN RAISE EXCEPTION 'Limite mensal do plano atingido'; END IF; INSERT INTO public.pending_publications(user_id,product_id,title,payload,reason) VALUES(p_user_id,p_product_id,p_title,p_payload,'image_compliance_unavailable') RETURNING id INTO result_id; RETURN result_id; END $$;
REVOKE ALL ON FUNCTION public.publication_image_gate(boolean),public.publication_image_pause(text,text,integer),public.publication_image_resume_after_success(),public.claim_publication_worker(uuid),public.release_publication_worker(uuid),public.enqueue_image_publication(uuid,text,text,jsonb,integer,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.publication_image_gate(boolean),public.publication_image_pause(text,text,integer),public.publication_image_resume_after_success(),public.claim_publication_worker(uuid),public.release_publication_worker(uuid),public.enqueue_image_publication(uuid,text,text,jsonb,integer,integer) TO service_role;